import{_ as l,l as i,o as e,c as n,v as o,p as s,x as t,d as c,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"NoC 路由与死锁避免","description":"","frontmatter":{"title":"NoC 路由与死锁避免","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/noc-routing-deadlock.md","filePath":"cs/noc-routing-deadlock.md","lastUpdated":1789023840000}'),p={name:"cs/noc-routing-deadlock.md"};function h(A,a,m,_,f,u){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="noc-路由与死锁避免" tabindex="-1">NoC 路由与死锁避免 <a class="header-anchor" href="#noc-路由与死锁避免" aria-label="Permalink to &quot;NoC 路由与死锁避免&quot;">​</a></h1><div class="epigraph"><p>包在网格里转弯会形成环形等待：每个路由器握着一个 flit 等下一个缓冲。维序路由禁止某些转弯，把依赖图变成无环。</p><footer>—— 据 Dally and Seitz, Deadlock-Free Message Routing in Multiprocessor Interconnection Networks, IEEE TC 1987 整理</footer></div><p><a href="/cs/interconnect-topologies">上一课</a> 选了图。最短路径若任意转弯，wormhole 路由下缓冲依赖可以成环，整网冻死。本课不重画 fat-tree。缺口是 <strong>路由：维序（XY）、虚通道、以及一致性消息为何特别怕死锁。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>wormhole：包拆 flit，头 flit 占路由，身子跟进，中间路由器只缓冲少许。若 A 等 B 的缓冲、B 等 A，死锁。<a href="/cs/directory-scalability">目录</a> 的请求-转发-ack 本身构成协议依赖，再叠网络依赖更危险。缺口不是加大缓冲到 store-and-forward 整包（面积炸），而是<strong>限制转弯或用虚通道打断环。</strong></p><p><span class="marginnote">Dally–Seitz：信道依赖图无环则死锁自由。XY 路由：先走 X 再走 Y，禁止 Y→X 转弯。虚通道：同一物理链路多队列，协议类或转弯类分通道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>确定性维序：简单、易证明、路径不自适应，热点绕不开。自适应路由：绕拥塞，但要额外虚通道保证无死锁。一致性：请求与应答分虚网络，避免「等 ack 的节点发不出请求」的协议死锁。</p>',8)),(e(),s(E,null,{default:t(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22XY%20%E7%BB%B4%E5%BA%8F%22%5D%20--%3E%20DAG%5B%22%E4%BF%A1%E9%81%93%E4%BE%9D%E8%B5%96%E6%97%A0%E7%8E%AF%22%5D%0A%20%20VC%5B%22%E8%99%9A%E9%80%9A%E9%81%93%22%5D%20--%3E%20SPLIT%5B%22%E6%89%93%E6%96%AD%E8%BD%AC%E5%BC%AF%E7%8E%AF%20%2F%20%E5%8D%8F%E8%AE%AE%E7%B1%BB%22%5D%0A%20%20ADAPT%5B%22%E8%87%AA%E9%80%82%E5%BA%94%22%5D%20--%3E%20NEED%5B%22%E6%9B%B4%E5%A4%9A%20VC%20%E6%89%8D%E5%AE%89%E5%85%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这与 OS <a href="/cs/deadlock-prevent">死锁预防</a> 同构：都是破环。NoC 不能超时重试当常规手段，因为一致性 ack 超时会破坏 <a href="/cs/mesi-protocol">MESI</a> 不变式。活锁：自适应一直绕，要限跳或最终确定性。</p><p>wormhole 的低缓冲是面积选择：每个虚通道几个 flit 槽。槽太少则依赖边更密、死锁窗口更大；槽太多则路由器面积回到「小交叉开关」。证明死锁自由是设计验收项，不是事后打补丁。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 turn model（west-first 等）列全。多 socket 的物理层与缓存代理下一课，可能仍用类似虚通道思想，介质换成板级或封装级。</p><p>后课默认：片上路由必须死锁自由；一致性分虚网络。出芯片的互连有另一套拓扑与协议封装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>wormhole + 任意转弯会死锁；维序或虚通道破环。</li><li>一致性请求/应答要分虚网络。</li><li>多路 socket 互连是下一课出片。</li><li>出处：Dally and Seitz, <em>IEEE TC</em>, 1987。</li></ul>',8))])}const k=l(p,[["render",h]]);export{D as __pageData,k as default};
